mapper.select:
SELECT LOGIN_HISTORY_ID, FACTORY_CODE, USER_ID, USER_NAME, CONVERT(VARCHAR(19), LOGIN_DT, 120) AS LOGIN_DT, LOGIN_IP, LOGIN_TYPE, USER_AGENT, LOGIN_RESULT, FAIL_REASON, CONVERT(VARCHAR(19), LOGOUT_DT, 120) AS LOGOUT_DT, SESSION_TIME, GOV_INTERFACE_YN, CONVERT(VARCHAR(23), GOV_INTERFACE_DT, 121) AS GOV_INTERFACE_DT, GOV_RECPTN_RSLT_CD, GOV_RECPTN_RSLT, GOV_RECPTN_RSLT_DTL, GOV_FAIL_REASON, GOV_REQUEST_JSON, GOV_RESPONSE_JSON FROM ( SELECT *, ROW_NUMBER() OVER (ORDER BY LOGIN_DT DESC) AS RNUM FROM TB_LoginHistory WHERE 1 = 1
AND FACTORY_CODE = #{factoryCode}
AND USER_ID LIKE '%' + #{searchUserId} + '%'
AND USER_NAME LIKE '%' + #{searchUserName} + '%'
AND LOGIN_RESULT = #{searchLoginResult}
AND LOGIN_DT >= CONVERT(DATETIME, #{searchStartDt})
AND LOGIN_DT <= CONVERT(DATETIME, #{searchEndDt} + ' 23:59:59')
) AS TEMP WHERE RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage} ORDER BY LOGIN_DT DESC
